import 'dart:math';import 'package:flutter/foundation.dart';enum NodeRole { peer, relay, coordinator }enum ReputationLevel { trustworthy, neutral, suspicious, blocked }class NodeMetrics {  final String nodeId;  final DateTime lastSeen;  final int successfulRelays;  final int failedRelays;  final List<int> latencySamples;  final int messagesDelivered;  final int messagesFailed;  final bool isOnline;  final NodeRole role;  NodeMetrics({    required this.nodeId,    required this.lastSeen,    this.successfulRelays = 0,    this.failedRelays = 0,    List<int>? latencySamples,    this.messagesDelivered = 0,    this.messagesFailed = 0,    this.isOnline = true,    this.role = NodeRole.peer,  }) : latencySamples = latencySamples ?? [];  double get averageLatency {    if (latencySamples.isEmpty) return 0;    return latencySamples.reduce((a, b) => a + b) / latencySamples.length;  }  double get relaySuccessRate {    final total = successfulRelays + failedRelays;    if (total == 0) return 0.5;    return successfulRelays / total;  }  double get deliveryRate {    final total = messagesDelivered + messagesFailed;    if (total == 0) return 1.0;    return messagesDelivered / total;  }  NodeMetrics copyWith({    String? nodeId,    DateTime? lastSeen,    int? successfulRelays,    int? failedRelays,    List<int>? latencySamples,    int? messagesDelivered,    int? messagesFailed,    bool? isOnline,    NodeRole? role,  }) {    return NodeMetrics(      nodeId: nodeId ?? this.nodeId,      lastSeen: lastSeen ?? this.lastSeen,      successfulRelays: successfulRelays ?? this.successfulRelays,      failedRelays: failedRelays ?? this.failedRelays,      latencySamples: latencySamples ?? this.latencySamples,      messagesDelivered: messagesDelivered ?? this.messagesDelivered,      messagesFailed: messagesFailed ?? this.messagesFailed,      isOnline: isOnline ?? this.isOnline,      role: role ?? this.role,    );  }}class NodeReputation {  final String nodeId;  final double score;  final ReputationLevel level;  final DateTime lastUpdated;  final List<String> behavioralFlags;  NodeReputation({    required this.nodeId,    required this.score,    required this.level,    required this.lastUpdated,    List<String>? behavioralFlags,  }) : behavioralFlags = behavioralFlags ?? [];  Map<String, dynamic> toJson() => {        'nodeId': nodeId,        'score': score,        'level': level.name,        'lastUpdated': lastUpdated.toIso8601String(),        'behavioralFlags': behavioralFlags,      };  factory NodeReputation.fromJson(Map<String, dynamic> json) {    return NodeReputation(      nodeId: json['nodeId'],      score: json['score'].toDouble(),      level: ReputationLevel.values.firstWhere(        (e) => e.name == json['level'],        orElse: () => ReputationLevel.neutral,      ),      lastUpdated: DateTime.parse(json['lastUpdated']),      behavioralFlags: List<String>.from(json['behavioralFlags'] ?? []),    );  }}class NodeReputationSystem {  static const double _maxScore = 100.0;  static const double _minScore = 0.0;  static const int _latencyWindowSize = 10;  final Map<String, NodeMetrics> _metrics = {};  final Map<String, NodeReputation> _reputations = {};  final Random _random = Random.secure();  final Set<String> _blockedNodes = {};  static const double _trustworthyThreshold = 75.0;  static const double _suspiciousThreshold = 30.0;  Future<void> recordRelayAttempt(      String nodeId, bool success, int latencyMs) async {    final metrics = _metrics[nodeId] ??        NodeMetrics(          nodeId: nodeId,          lastSeen: DateTime.now(),        );    final updatedLatencies = List<int>.from(metrics.latencySamples);    updatedLatencies.add(latencyMs);    if (updatedLatencies.length > _latencyWindowSize) {      updatedLatencies.removeAt(0);    }    _metrics[nodeId] = metrics.copyWith(      lastSeen: DateTime.now(),      successfulRelays: success ? metrics.successfulRelays + 1 : null,      failedRelays: success ? null : metrics.failedRelays + 1,      latencySamples: updatedLatencies,      isOnline: true,    );    await _updateReputation(nodeId);  }  Future<void> recordMessageDelivery(String nodeId, bool success) async {    final metrics = _metrics[nodeId] ??        NodeMetrics(          nodeId: nodeId,          lastSeen: DateTime.now(),        );    _metrics[nodeId] = metrics.copyWith(      lastSeen: DateTime.now(),      messagesDelivered: success ? metrics.messagesDelivered + 1 : null,      messagesFailed: success ? null : metrics.messagesFailed + 1,      isOnline: true,    );    await _updateReputation(nodeId);  }  Future<void> updateNodeOnlineStatus(String nodeId, bool isOnline) async {    final metrics = _metrics[nodeId];    if (metrics != null) {      _metrics[nodeId] = metrics.copyWith(        isOnline: isOnline,        lastSeen: DateTime.now(),      );      await _updateReputation(nodeId);    }  }  Future<void> setNodeRole(String nodeId, NodeRole role) async {    final metrics = _metrics[nodeId] ??        NodeMetrics(          nodeId: nodeId,          lastSeen: DateTime.now(),        );    _metrics[nodeId] = metrics.copyWith(role: role);  }  Future<void> _updateReputation(String nodeId) async {    final metrics = _metrics[nodeId];    if (metrics == null) return;    double score = 50.0;    final relayWeight = 0.3;    score += (metrics.relaySuccessRate - 0.5) * 20 * relayWeight;    final deliveryWeight = 0.3;    score += (metrics.deliveryRate - 0.5) * 20 * deliveryWeight;    if (metrics.latencySamples.isNotEmpty) {      final latencyWeight = 0.2;      final avgLatency = metrics.averageLatency;      if (avgLatency < 100) {        score += 10 * latencyWeight;      } else if (avgLatency < 500) {        score += 5 * latencyWeight;      } else if (avgLatency > 2000) {        score -= 10 * latencyWeight;      }    }    final recencyWeight = 0.2;    final timeSinceLastSeen = DateTime.now().difference(metrics.lastSeen);    if (timeSinceLastSeen.inMinutes < 5) {      score += 10 * recencyWeight;    } else if (timeSinceLastSeen.inHours > 1) {      score -= 5 * recencyWeight;    }    if (metrics.failedRelays > 10 && metrics.relaySuccessRate < 0.3) {      score -= 15;    }    score = score.clamp(_minScore, _maxScore);    ReputationLevel level;    List<String> flags = [];    if (_blockedNodes.contains(nodeId)) {      level = ReputationLevel.blocked;      score = 0;      flags.add('manually_blocked');    } else if (score >= _trustworthyThreshold) {      level = ReputationLevel.trustworthy;    } else if (score < _suspiciousThreshold) {      level = ReputationLevel.suspicious;      flags.add('low_reputation');    } else {      level = ReputationLevel.neutral;    }    _reputations[nodeId] = NodeReputation(      nodeId: nodeId,      score: score,      level: level,      lastUpdated: DateTime.now(),      behavioralFlags: flags,    );  }  NodeReputation? getReputation(String nodeId) => _reputations[nodeId];  NodeMetrics? getMetrics(String nodeId) => _metrics[nodeId];  ReputationLevel getReputationLevel(String nodeId) {    return _reputations[nodeId]?.level ?? ReputationLevel.neutral;  }  double getReputationScore(String nodeId) {    return _reputations[nodeId]?.score ?? 50.0;  }  bool isNodeBlocked(String nodeId) {    return _blockedNodes.contains(nodeId) ||        getReputationLevel(nodeId) == ReputationLevel.blocked;  }  Future<void> blockNode(String nodeId, {String reason = ''}) async {    _blockedNodes.add(nodeId);    await _updateReputation(nodeId);    debugPrint('Node $nodeId blocked: $reason');  }  Future<void> unblockNode(String nodeId) async {    _blockedNodes.remove(nodeId);    await _updateReputation(nodeId);  }  List<String> getTrustworthyRelays({int limit = 5}) {    final relays = _metrics.entries        .where((e) => e.value.role != NodeRole.coordinator)        .where((e) => getReputationLevel(e.key) == ReputationLevel.trustworthy)        .where((e) => e.value.isOnline)        .toList();    relays.sort((a, b) {      final scoreA = getReputationScore(a.key);      final scoreB = getReputationScore(b.key);      return scoreB.compareTo(scoreA);    });    return relays.take(limit).map((e) => e.key).toList();  }  List<String> getReliableRoutes(String destinationId, {int maxHops = 3}) {    final routes = <List<String>>[];    final visited = <String>{};    void dfs(String current, List<String> path, int depth) {      if (depth > maxHops || visited.contains(current)) return;      visited.add(current);      path.add(current);      if (current == destinationId) {        routes.add(List.from(path));      } else {        final onlineNodes = _metrics.entries            .where((e) => e.value.isOnline)            .where((e) => !isNodeBlocked(e.key))            .map((e) => e.key)            .toList();        for (final next in onlineNodes) {          if (!visited.contains(next)) {            dfs(next, path, depth + 1);          }        }      }      path.removeLast();      visited.remove(current);    }    dfs(destinationId, [], 0);    routes.sort((a, b) {      double routeScore(List<String> route) {        return route                .map((nodeId) => getReputationScore(nodeId))                .reduce((a, b) => a + b) /            route.length;      }      return routeScore(b).compareTo(routeScore(a));    });    return routes.isEmpty ? [] : routes.first;  }  Map<String, NodeReputation> getAllReputations() =>      Map.unmodifiable(_reputations);  Map<String, NodeMetrics> getAllMetrics() => Map.unmodifiable(_metrics);  Future<void> decayReputations() async {    for (final entry in _reputations.entries) {      final metrics = _metrics[entry.key];      if (metrics == null) continue;      final timeSinceLastSeen = DateTime.now().difference(metrics.lastSeen);      if (timeSinceLastSeen.inHours > 24) {        final decayFactor = (timeSinceLastSeen.inHours - 24) / 168;        final newScore = (entry.value.score * (1 - decayFactor * 0.5))            .clamp(_minScore, _maxScore);        _reputations[entry.key] = NodeReputation(          nodeId: entry.key,          score: newScore,          level: entry.value.level,          lastUpdated: DateTime.now(),          behavioralFlags: entry.value.behavioralFlags,        );      }    }  }  Future<void> cleanupOldData(Duration maxAge) async {    final cutoff = DateTime.now().subtract(maxAge);    _metrics.removeWhere((_, metrics) => metrics.lastSeen.isBefore(cutoff));    _reputations.removeWhere((_, rep) => rep.lastUpdated.isBefore(cutoff));  }  double calculateRouteQuality(List<String> route) {    if (route.isEmpty) return 0;    double totalScore = 0;    for (final nodeId in route) {      totalScore += getReputationScore(nodeId);    }    return totalScore / route.length;  }  Map<String, dynamic> getNetworkHealthReport() {    final totalNodes = _metrics.length;    final onlineNodes = _metrics.values.where((m) => m.isOnline).length;    final trustworthyNodes = _reputations.values        .where((r) => r.level == ReputationLevel.trustworthy)        .length;    final suspiciousNodes = _reputations.values        .where((r) => r.level == ReputationLevel.suspicious)        .length;    final blockedNodes = _blockedNodes.length;    final avgLatency = _metrics.values            .where((m) => m.latencySamples.isNotEmpty)            .map((m) => m.averageLatency)            .fold(0.0, (a, b) => a + b) /        (_metrics.values            .where((m) => m.latencySamples.isNotEmpty)            .length            .clamp(1, totalNodes));    return {      'totalNodes': totalNodes,      'onlineNodes': onlineNodes,      'offlineNodes': totalNodes - onlineNodes,      'trustworthyNodes': trustworthyNodes,      'suspiciousNodes': suspiciousNodes,      'blockedNodes': blockedNodes,      'averageLatencyMs': avgLatency.round(),      'networkHealth':          onlineNodes > 0 ? (trustworthyNodes / onlineNodes * 100) : 0,    };  }}